template.script:
document.getElementById('cookie_ok_btn') && document.getElementById('cookie_ok_btn').addEventListener('click', function(e) {
    e.preventDefault();
    fetch('/website_cookie_notice/ok', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}}),
    }).then(function() {
        var b = document.getElementById('website_cookie_notice');
        if (b) b.style.display = 'none';
    });
});
